blocks.model_answer:
```cpp
class DepartCourse
{
private:
    PcoSemaphore mutex;
    PcoSemaphore attenteDepart;
    bool coupDeFeuTire;
    unsigned int nbCoureursEnAttente;

public:
    DepartCourse()
        : mutex(1), attenteDepart(0), coupDeFeuTire(false), nbCoureursEnAttente(0)
    {
    }

    bool coureurArrive()
    {
        mutex.acquire();
        if (coupDeFeuTire) {
            mutex.release();
            return false;
        }
        nbCoureursEnAttente++;
        mutex.release();

        attenteDepart.acquire();
        return true;
    }

    void coupDeFeu()
    {
        mutex.acquire();
        coupDeFeuTire = true;
        while (nbCoureursEnAttente > 0) {
            nbCoureursEnAttente--;
            attenteDepart.release();
        }
        mutex.release();
    }
};
```

**Points clés :**
* `mutex` protège à la fois `coupDeFeuTire` et `nbCoureursEnAttente`.
* Un coureur arrivant avant `coupDeFeu()` incrémente `nbCoureursEnAttente` et relâche `mutex` *avant* de bloquer sur `attenteDepart.acquire()`, afin de ne pas bloquer le commissaire.
* `coupDeFeu()` réveille exactement le nombre de coureurs présents (`nbCoureursEnAttente`), sans laisser de jetons résiduels dans `attenteDepart`.

